// Claude 自動レビュー本文の整形・判定ロジック（純関数）。
// workflow の inline JS から切り出し、tests/unit/claude-review-format.test.ts で
// 検証する。伏字化は正規表現ベースのベストエフォートな緩和であり、最終防壁は
// workflow 側の生トークン完全一致チェック（トークンへ到達できる唯一の job にある）。
// 変更時は必ずテストを更新すること。

// 既知のトークン形式。GitHub のシークレットマスキングはログにのみ効き、
// API のコメント本文には適用されないため、投稿前に伏字化する。
// 末尾に否定先読みを置かない: 貪欲マッチと組み合わせると
// `ghp_..._` や `github_pat_...-` のような実トークンが素通りする
// fail-open になるため。過剰伏字化は安全側。
// \b は付けない: 語構成文字直後のトークン（`Xsk-ant-...` 等）が素通りする
// fail-open になるため。過剰伏字化は安全側。
const SECRET_PATTERN =
  /(sk-ant-[A-Za-z0-9_-]{10,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/g

// issue comment 上限 65536 文字に対して余裕を持つしきい値。
// プロンプトで 6000 字以内を指示しているが出力は強制されないため、
// 大規模 PR でも実質発火しない大きめの値で安全網として機能させる。
export const MAX_BODY_LENGTH = 60000

export function redactSecrets(text) {
  // String.prototype.replace は /g 正規表現の lastIndex を走査前後にリセットする
  // ため、モジュール定数を共有して安全。stateful な .test()/.exec() には使わないこと。
  return text.replace(SECRET_PATTERN, '[REDACTED]')
}

// 本文長が上限を超えた場合は切り詰める。未閉じのコードフェンスは切り詰めの有無に
// 関わらず常に補完し、切り詰め時はフェンスを閉じてから省略注記を足す。
// 返り値は本文部分を MAX_BODY_LENGTH 以内に保ち、閉じフェンスと注記を加算する
// （最大 +16 コードポイント。issue comment 上限 65536 に対して十分な余裕がある）。
// 既知の劣化（いずれも表示崩れのみ）: slice は UTF-16 単位のためサロゲートペアを
// 分断し得る。また切り詰め位置が ``` の途中に落ちた場合はフェンスとして数えられず、
// 補完と合わさって表示が崩れ得る。
export function truncateAndCloseFences(text) {
  const needsTruncation = text.length > MAX_BODY_LENGTH
  let result = needsTruncation ? text.slice(0, MAX_BODY_LENGTH) : text
  // 行頭の ``` のみ数える簡易ヒューリスティック（4連バッククォートの入れ子や
  // フェンス内の例示は誤判定し得る。4連バッククォートで開いたブロックは
  // 閉じられずフッターがコードブロックに飲み込まれることもあるが表示崩れのみ）。
  const fenceCount = result
    .split('\n')
    .filter((line) => line.trim().startsWith('```')).length
  if (fenceCount % 2 === 1) {
    result += '\n```'
  }
  if (needsTruncation) {
    result += '\n\n（長すぎるため省略）'
  }
  return result
}

// structured_output の JSON から review 本文を取り出す。
// review フィールドが空・空白のみの場合は null を返す（呼び出し側で failure にする）。
// JSON として壊れている場合は throw する。
export function parseReviewJson(json) {
  const { review } = JSON.parse(json)
  if (typeof review !== 'string' || review.trim() === '') {
    return null
  }
  return review.trim()
}

// レビュー本文から投稿コメント本文を組み立てる。伏字化 → 切り詰め → 組み立ての
// 順序を1箇所に固定する（順序が逆転すると伏字化が効かなくなるため、テストで
// 回帰を守る）。
export function buildReviewCommentBody({ marker, shortSha, commitUrl, runUrl, reviewText }) {
  const safe = truncateAndCloseFences(redactSecrets(reviewText))
  return (
    `${marker}\n## Claude Auto Review\n\n` +
    `Reviewed commit: [\`${shortSha}\`](${commitUrl})\n\n` +
    `${safe}\n\n` +
    `*Generated by Claude Code (opus) · [Run](${runUrl})*`
  )
}

// このワークフローが投稿した既存レビューコメントかを判定する。
// マーカーは誰でも知り得るため、投稿者をワークフローの github-token が
// 生み出す投稿者ログインに限定して第三者（他のボット含む）コメントの誤上書きを
// 防ぐ。投稿者は workflow 側の `github-token` で決まるため、トークンを
// 差し替える場合は期待ログインも変更すること。
export const REVIEW_COMMENT_AUTHOR = 'github-actions[bot]'

// 先頭行がマーカーかどうか（GitHub API が \r\n を返し得るため trim する）。
export function hasReviewMarker(comment, marker) {
  return comment.body?.split('\n', 1)[0].trim() === marker
}

export function isOwnReviewComment(comment, marker) {
  return comment?.user?.login === REVIEW_COMMENT_AUTHOR && hasReviewMarker(comment, marker)
}
